def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.item_emb(seq)
    same_item = seq.unsqueeze(2).eq(seq.unsqueeze(1))
    earlier_counts = same_item.tril(diagonal=-1).sum(dim=-1)
    repeat_counts = earlier_counts.clamp_max(3) * seq.ne(0)
    scale = 1.0 + 0.1 * repeat_counts.to(dtype=emb.dtype)
    return self.dropout(emb * scale.unsqueeze(-1))

def encode(self, seq: torch.Tensor) -> torch.Tensor:
